'use strict';
/* Shared language, links, accessibility and email-draft fallback helpers. */
window.SiteUI={
 initialLanguage(){let lang=new URLSearchParams(location.search).get('lang');if(!['en','th'].includes(lang)){try{lang=localStorage.getItem('lopburi-language')}catch{}}return ['en','th'].includes(lang)?lang:'en'},
 text(key,lang=document.documentElement.lang){return SITE_COMMON_COPY[key]?.[lang]||key},
 sync(lang){
  document.querySelectorAll('[data-i18n-aria-label]').forEach(e=>e.setAttribute('aria-label',this.text(e.dataset.i18nAriaLabel,lang)));
  document.querySelectorAll('[data-i18n-alt]').forEach(e=>e.alt=this.text(e.dataset.i18nAlt,lang));
  for(const a of document.querySelectorAll('a[href]')){const href=a.getAttribute('href');if(href.startsWith('#'))continue;const url=new URL(href,location.href),base=new URL('.',location.href);if(url.href.startsWith(base.href)&&/\/(index|events|resources|privacy)\.html$/.test(url.pathname)){url.searchParams.set('lang',lang);a.href=url.href}}
 },
 emailLink(anchor,address,subject,body,note){
  const prefix='mailto:'+address+'?subject='+encodeURIComponent(subject),full=prefix+'&body='+encodeURIComponent(body),long=full.length>1800;
  anchor.href=long?prefix:full;anchor.dataset.longMessage=String(long);
  note.hidden=!long;note.textContent=this.text('longMessage');
  // Never silently truncate a draft or omit its consent/route metadata.
 },
 async copy(pre,status){try{if(!navigator.clipboard?.writeText)throw Error('No clipboard');await navigator.clipboard.writeText(pre.textContent);status.textContent=this.text('copiedMessage')}catch{const selection=getSelection(),range=document.createRange();range.selectNodeContents(pre);selection.removeAllRanges();selection.addRange(range);status.textContent=this.text('selectMessage')}},
 save(pre,status,name){const url=URL.createObjectURL(new Blob([pre.textContent],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);status.textContent=this.text('savedMessage')}
};

// About always targets section 01, after fonts and the hero's sticky height are
// established. Native early hash positioning could otherwise land in the hero.
(()=>{
 const align=()=>{const target=document.getElementById('purpose');if(!target)return;const h=document.querySelector('.site-header')?.getBoundingClientRect().height||0;window.scrollTo({top:target.getBoundingClientRect().top+scrollY-h-16,behavior:'instant'});};
 const settle=()=>Promise.resolve(document.fonts?.ready).then(()=>requestAnimationFrame(align));
 document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(!a||e.defaultPrevented||e.button!==0||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||a.target==='_blank')return;const u=new URL(a.href,location.href);if(u.origin===location.origin&&u.pathname===location.pathname&&u.hash==='#purpose'&&document.getElementById('purpose')){e.preventDefault();history.pushState(null,'',u);settle();}});
 window.addEventListener('load',()=>{if(location.hash==='#purpose')settle()});
 window.addEventListener('hashchange',()=>{if(location.hash==='#purpose')settle()});
})();
